const B1 = [19, 4.5], B2 = [7, 17.5], FOOT = 4.8, LIMIT = 66, HMAX = 46, PB = 5;
const DET = B1[0] * B2[1] - B1[1] * B2[0];

/** Coefficients of a ground point in the basis (real-valued). */
